 function init(){tabs();loadPreset();$('#preset').addEventListener('change',()=>{loadPreset();stale();});document.querySelectorAll('.controls input,.controls select').forEach(el=>el.addEventListener('input',stale));$('#run').addEventListener('click',run);$('#reset').addEventListener('click',reset);$('#export').addEventListener('click',save);$('#rate-slice').addEventListener('change',()=>{if(state.result)renderMap(state.result);});$('#review').addEventListener('click',()=>{if(state.status!=='completed'){$('#review-state').textContent='请先重算当前设置';return;}if(!state.selected||state.selected.issues.length){$('#review-state').textContent='请选择一个可行候选';return;}const note=$('#review-note').value.trim();if(!note){$('#review-state').textContent='请填写具体复核意见';return;}state.review={runId:state.runId,candidate:state.selected.observation,note,outOfDomain:state.result.outOfDomain,time:new Date().toISOString()};state.reviewHistory.push({...state.review});$('#review-state').textContent='当前候选复核意见已记录';});}
 g.CaseInspect={exportPayload:payload,snapshot:()=>({sceneId:'e1',caseId:'s17x-e1-fracture-optimization',status:state.status,metrics:state.result?.metrics??null,runId:state.runId,params:state.status==='completed'?state.params:(()=>{try{return {preset:$('#preset')?.value,...settings()};}catch{return null;}})(),selectedCandidate:state.selected?.observation??null,review:state.review})};
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
